// BIP-173 bech32 encoder helper (hypothesis to be validated against the binary)
const CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";
function polymod(v){const G=[0x3b6a57b2,0x26508e6d,0x1ea119fa,0x3d4233dd,0x2a1462b3];let c=1;
 for(const d of v){const b=c>>25;c=((c&0x1ffffff)<<5)^d;for(let i=0;i<5;i++) if((b>>i)&1) c^=G[i];}return c;}
function hrpExpand(h){const a=[],b=[];for(const ch of h){a.push(ch.charCodeAt(0)>>5);b.push(ch.charCodeAt(0)&31);}return a.concat([0],b);}
function createChecksum(hrp,data){const v=hrpExpand(hrp).concat(data).concat([0,0,0,0,0,0]);
 const m=polymod(v)^1;const out=[];for(let i=0;i<6;i++)out.push((m>>(5*(5-i)))&31);return out;}
function encode(hrp,data){const chk=createChecksum(hrp,data);return hrp+"1"+data.concat(chk).map(d=>CHARSET[d]).join("");}
function convertbits(data,from,to,pad){let acc=0,bits=0;const ret=[];const maxv=(1<<to)-1;
 for(const v of data){acc=(acc<<from)|v;bits+=from;while(bits>=to){bits-=to;ret.push((acc>>bits)&maxv);}}
 if(pad){if(bits) ret.push((acc<<(to-bits))&maxv);}else if(bits>=from||((acc<<(to-bits))&maxv))return null;return ret;}
function segwitEncode(hrp,ver,prog){return encode(hrp,[ver].concat(convertbits(prog,8,5,true)));}
module.exports={CHARSET,encode,convertbits,segwitEncode,polymod,hrpExpand,createChecksum};
if(require.main===module){
